 book:'<path d="M12 5C8 2 5 3 2 4v15c4-1 7-1 10 1 3-2 6-2 10-1V4c-3-1-6-2-10 1v15"/>',
 chart:'<path d="M4 3v18h17M8 16v-5m5 5V6m5 10v-8"/>',
 arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>', chevron:'<path d="m9 5 7 7-7 7"/>',
